static void backtrack(char **res, int *size, char *cur, int len, int open, int close, int n) {
  if (len == n * 2) {
    cur[len] = '\0';
    res[*size] = strdup(cur);
    (*size)++;
    return;
  }
  if (open < n) {
    cur[len] = '(';
    backtrack(res, size, cur, len + 1, open + 1, close, n);
  }
  if (close < open) {
    cur[len] = ')';
    backtrack(res, size, cur, len + 1, open, close + 1, n);
  }
}

char **generateParenthesis(int n, int *returnSize) {
  char **res = (char **)malloc(sizeof(char *) * 20000);
  char *cur = (char *)malloc(sizeof(char) * (n * 2 + 1));
  *returnSize = 0;
  backtrack(res, returnSize, cur, 0, 0, 0, n);
  free(cur);
  return res;
}

func generateParenthesis(n int) []string {
	var res []string
	var backtrack func(cur string, open, close int)
	backtrack = func(cur string, open, close int) {
		if len(cur) == n*2 {
			res = append(res, cur)
			return
		}
		if open < n {
			backtrack(cur+"(", open+1, close)
		}
		if close < open {
			backtrack(cur+")", open, close+1)
		}
	}
	backtrack("", 0, 0)
	return res
}

class Solution {
  public List<String> generateParenthesis(int n) {
    List<String> res = new ArrayList<>();
    backtrack(res, new StringBuilder(), 0, 0, n);
    return res;
  }

  private void backtrack(List<String> res, StringBuilder cur, int open, int close, int n) {
    if (cur.length() == n * 2) {
      res.add(cur.toString());
      return;
    }
    if (open < n) {
      cur.append('(');
      backtrack(res, cur, open + 1, close, n);
      cur.deleteCharAt(cur.length() - 1);
    }
    if (close < open) {
      cur.append(')');
      backtrack(res, cur, open, close + 1, n);
      cur.deleteCharAt(cur.length() - 1);
    }
  }
}

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        res = []

        def backtrack(cur: str, open_: int, close: int):
            if len(cur) == n * 2:
                res.append(cur)
                return
            if open_ < n:
                backtrack(cur + "(", open_ + 1, close)
            if close < open_:
                backtrack(cur + ")", open_, close + 1)

        backtrack("", 0, 0)
        return res

impl Solution {
  pub fn generate_parenthesis(n: i32) -> Vec<String> {
    fn backtrack(res: &mut Vec<String>, cur: &mut String, open: i32, close: i32, n: i32) {
      if cur.len() == (n * 2) as usize {
        res.push(cur.clone());
        return;
      }
      if open < n {
        cur.push('(');
        backtrack(res, cur, open + 1, close, n);
        cur.pop();
      }
      if close < open {
        cur.push(')');
        backtrack(res, cur, open, close + 1, n);
        cur.pop();
      }
    }
    let mut res = vec![];
    let mut cur = String::new();
    backtrack(&mut res, &mut cur, 0, 0, n);
    res
  }
}

const generateParenthesis = (n: number): string[] => {
  const res: string[] = [];

  const backtrack = (cur: string, open: number, close: number) => {
    if (cur.length === n * 2) {
      res.push(cur);
      return;
    }
    if (open < n) backtrack(cur + '(', open + 1, close);
    if (close < open) backtrack(cur + ')', open, close + 1);
  };

  backtrack('', 0, 0);
  return res;
};
